doc := gowkhtmltopdf.Document{
	PageSize: "A4",
	Pages: []gowkhtmltopdf.Page{{
		Source: gowkhtmltopdf.File("invoice.html"),
	}},
	AllowLocalFiles: true,
}

file, err := os.Create("invoice.pdf")
if err != nil {
	return err
}
defer file.Close()

return doc.WritePDF(ctx, file)

image := gowkhtmltopdf.ImageDocument{
	Source: gowkhtmltopdf.HTML([]byte("<h1>Preview</h1>")),
	Width: 1024,
	Format: "png",
}

bytes, err := image.Image(ctx)
if err != nil {
	return err
}
return os.WriteFile("preview.png", bytes, 0o644)
